// : number 
// 위와 같은 형태를 타입주석 또는 type annotation이라고 한다.
// number
let num1 = 123;
let num2 = -123;
let num3 = 0.123;
let num4 = -0.123;
let num5 = Infinity;
let num6 = -Infinity;
let num7 = NaN;
// string
let str1 = "hello";
let str2 = 'hello';
let str3 = `hello`;
let str4 = `hello ${num1}`;
// boolean
let bool1 = true;
let bool2 = false;
// null
let null1 = null;
// undefined
let unde1 = undefined;
// "strictNullChecks": false,
let numA = null;
// 리터럴타입
// 리터럴 -> 값
// 값이 고정된 타입
let numB = 10;
export {};
// numB = 12 오류발생
